CREATE TABLE "GrowthLead" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "org" TEXT, "type" TEXT NOT NULL DEFAULT 'gym', "email" TEXT, "phone" TEXT, "source" TEXT, "stage" TEXT NOT NULL DEFAULT 'new', "aiBrief" TEXT, "notes" TEXT, "needsAction" BOOLEAN NOT NULL DEFAULT false, "nextTouchAt" DATETIME, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE INDEX "GrowthLead_stage_nextTouchAt_idx" ON "GrowthLead"("stage", "nextTouchAt");
CREATE INDEX "GrowthLead_needsAction_idx" ON "GrowthLead"("needsAction");
CREATE TABLE "GrowthTouch" ("id" TEXT NOT NULL PRIMARY KEY, "leadId" TEXT NOT NULL, "direction" TEXT NOT NULL, "channel" TEXT NOT NULL DEFAULT 'email', "subject" TEXT, "body" TEXT NOT NULL, "aiDrafted" BOOLEAN NOT NULL DEFAULT false, "status" TEXT NOT NULL DEFAULT 'draft', "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "GrowthTouch_leadId_fkey" FOREIGN KEY ("leadId") REFERENCES "GrowthLead" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "GrowthTouch_leadId_createdAt_idx" ON "GrowthTouch"("leadId", "createdAt");
CREATE TABLE "MarketingAsset" ("id" TEXT NOT NULL PRIMARY KEY, "kind" TEXT NOT NULL DEFAULT 'reel', "filePath" TEXT NOT NULL, "caption" TEXT, "active" BOOLEAN NOT NULL DEFAULT true, "usedCount" INTEGER NOT NULL DEFAULT 0, "lastUsedAt" DATETIME, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
